import{_ as e,o,c as t,a2 as r}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"常见问题 FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"zh/appendix/faq.md","filePath":"zh/appendix/faq.md"}'),d={name:"zh/appendix/faq.md"};function l(h,a,i,q,n,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题-faq" tabindex="-1">常见问题 FAQ <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题 FAQ&quot;">​</a></h1><hr><h2 id="安装与登录" tabindex="-1">安装与登录 <a class="header-anchor" href="#安装与登录" aria-label="Permalink to &quot;安装与登录&quot;">​</a></h2><h3 id="q1-codex-桌面-app-在哪里下载" tabindex="-1">Q1：Codex 桌面 App 在哪里下载？ <a class="header-anchor" href="#q1-codex-桌面-app-在哪里下载" aria-label="Permalink to &quot;Q1：Codex 桌面 App 在哪里下载？&quot;">​</a></h3><p>A：通过 ChatGPT 官网（chatgpt.com）登录后，在左侧菜单找到 &quot;Codex&quot; 入口即可下载。也可以直接在 ChatGPT 网页版中使用 Code Interpreter 功能。</p><h3 id="q2-免费版可以用-codex-吗" tabindex="-1">Q2：免费版可以用 Codex 吗？ <a class="header-anchor" href="#q2-免费版可以用-codex-吗" aria-label="Permalink to &quot;Q2：免费版可以用 Codex 吗？&quot;">​</a></h3><p>A：可以，但免费版的额度有限。如果你经常使用，建议升级到 Plus（$20/月）或 Pro（$200/月）。</p><h3 id="q3-登录时提示-账号未激活-怎么办" tabindex="-1">Q3：登录时提示&quot;账号未激活&quot;怎么办？ <a class="header-anchor" href="#q3-登录时提示-账号未激活-怎么办" aria-label="Permalink to &quot;Q3：登录时提示&quot;账号未激活&quot;怎么办？&quot;">​</a></h3><p>A：请检查你的注册邮箱，确认已完成验证。如果找不到验证邮件，检查垃圾邮件文件夹，或者重新发送验证邮件。</p><h3 id="q4-mac-上首次打开-codex-提示-来自未识别开发者" tabindex="-1">Q4：Mac 上首次打开 Codex 提示&quot;来自未识别开发者&quot;？ <a class="header-anchor" href="#q4-mac-上首次打开-codex-提示-来自未识别开发者" aria-label="Permalink to &quot;Q4：Mac 上首次打开 Codex 提示&quot;来自未识别开发者&quot;？&quot;">​</a></h3><p>A：这是 macOS 的安全机制。进入&quot;系统偏好设置 → 安全性与隐私&quot;，在&quot;通用&quot;标签页中点击&quot;仍然打开&quot;即可。</p><hr><h2 id="权限与工作区" tabindex="-1">权限与工作区 <a class="header-anchor" href="#权限与工作区" aria-label="Permalink to &quot;权限与工作区&quot;">​</a></h2><h3 id="q5-什么是工作区-为什么需要设置" tabindex="-1">Q5：什么是工作区？为什么需要设置？ <a class="header-anchor" href="#q5-什么是工作区-为什么需要设置" aria-label="Permalink to &quot;Q5：什么是工作区？为什么需要设置？&quot;">​</a></h3><p>A：工作区是 Codex 操作文件的范围。设置工作区可以：</p><ul><li>保护你电脑上的其他文件不被意外修改</li><li>让 Codex 更好地理解你的项目结构</li><li>方便追踪和管理 AI 的修改记录</li></ul><h3 id="q6-三种权限模式有什么区别" tabindex="-1">Q6：三种权限模式有什么区别？ <a class="header-anchor" href="#q6-三种权限模式有什么区别" aria-label="Permalink to &quot;Q6：三种权限模式有什么区别？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>推荐度</th></tr></thead><tbody><tr><td>默认权限</td><td>Codex 操作前征求你的同意</td><td>⭐⭐⭐ 新手首选</td></tr><tr><td>自动审查</td><td>Codex 自动执行，你事后审计</td><td>⭐⭐ 进阶用户</td></tr><tr><td>完全访问</td><td>Codex 拥有完全控制权</td><td>⚠️ 不推荐</td></tr></tbody></table><h3 id="q7-如何更改权限模式" tabindex="-1">Q7：如何更改权限模式？ <a class="header-anchor" href="#q7-如何更改权限模式" aria-label="Permalink to &quot;Q7：如何更改权限模式？&quot;">​</a></h3><p>A：在 Codex 的设置界面中找到&quot;权限管理&quot;或&quot;安全设置&quot;，选择你想要的模式即可。</p><hr><h2 id="使用问题" tabindex="-1">使用问题 <a class="header-anchor" href="#使用问题" aria-label="Permalink to &quot;使用问题&quot;">​</a></h2><h3 id="q8-codex-生成的代码-内容不正确怎么办" tabindex="-1">Q8：Codex 生成的代码/内容不正确怎么办？ <a class="header-anchor" href="#q8-codex-生成的代码-内容不正确怎么办" aria-label="Permalink to &quot;Q8：Codex 生成的代码/内容不正确怎么办？&quot;">​</a></h3><p>A：不要担心，这是正常现象。你可以：</p><ol><li>告诉 Codex 哪里不对，让它修正</li><li>提供更详细的背景信息</li><li>把大任务拆成小步骤逐步完成</li></ol><h3 id="q9-codex-能操作我电脑上的所有文件吗" tabindex="-1">Q9：Codex 能操作我电脑上的所有文件吗？ <a class="header-anchor" href="#q9-codex-能操作我电脑上的所有文件吗" aria-label="Permalink to &quot;Q9：Codex 能操作我电脑上的所有文件吗？&quot;">​</a></h3><p>A：不能。Codex 只能在它被授权的工作区内操作文件。这是出于安全考虑的设计。</p><h3 id="q10-codex-会保存我的数据吗" tabindex="-1">Q10：Codex 会保存我的数据吗？ <a class="header-anchor" href="#q10-codex-会保存我的数据吗" aria-label="Permalink to &quot;Q10：Codex 会保存我的数据吗？&quot;">​</a></h3><p>A：Codex 的使用记录保存在你的 ChatGPT 账号中。它不会将你的私人文件上传到外部服务器。你可以在 ChatGPT 设置中管理数据保留选项。</p><h3 id="q11-codex-支持中文指令吗" tabindex="-1">Q11：Codex 支持中文指令吗？ <a class="header-anchor" href="#q11-codex-支持中文指令吗" aria-label="Permalink to &quot;Q11：Codex 支持中文指令吗？&quot;">​</a></h3><p>A：支持。Codex 理解多种语言，包括中文、英文等。你可以用你最舒服的语言来指挥它。</p><hr><h2 id="额度和费用" tabindex="-1">额度和费用 <a class="header-anchor" href="#额度和费用" aria-label="Permalink to &quot;额度和费用&quot;">​</a></h2><h3 id="q12-codex-使用消耗额度吗" tabindex="-1">Q12：Codex 使用消耗额度吗？ <a class="header-anchor" href="#q12-codex-使用消耗额度吗" aria-label="Permalink to &quot;Q12：Codex 使用消耗额度吗？&quot;">​</a></h3><p>A：是的。每次对话都会消耗一定的 ChatGPT 额度。Plus 用户每月有充足额度，Pro 用户额度更多。</p><h3 id="q13-额度用完了怎么办" tabindex="-1">Q13：额度用完了怎么办？ <a class="header-anchor" href="#q13-额度用完了怎么办" aria-label="Permalink to &quot;Q13：额度用完了怎么办？&quot;">​</a></h3><p>A：</p><ul><li>等待下月重置（按月计费）</li><li>升级到更高版本</li><li>使用免费版（额度较少）</li></ul><h3 id="q14-如何查看当前剩余额度" tabindex="-1">Q14：如何查看当前剩余额度？ <a class="header-anchor" href="#q14-如何查看当前剩余额度" aria-label="Permalink to &quot;Q14：如何查看当前剩余额度？&quot;">​</a></h3><p>A：在 ChatGPT 设置中可以看到你的计划类型和剩余额度信息。</p><hr><h2 id="安全与隐私" tabindex="-1">安全与隐私 <a class="header-anchor" href="#安全与隐私" aria-label="Permalink to &quot;安全与隐私&quot;">​</a></h2><h3 id="q15-在-codex-中输入敏感信息安全吗" tabindex="-1">Q15：在 Codex 中输入敏感信息安全吗？ <a class="header-anchor" href="#q15-在-codex-中输入敏感信息安全吗" aria-label="Permalink to &quot;Q15：在 Codex 中输入敏感信息安全吗？&quot;">​</a></h3><p>A：<strong>不建议</strong>。永远不要在 Codex 中输入密码、银行卡号、身份证号等敏感信息。Codex 虽然安全，但这些信息不应该出现在任何 AI 对话中。</p><h3 id="q16-codex-会泄露我的文件内容吗" tabindex="-1">Q16：Codex 会泄露我的文件内容吗？ <a class="header-anchor" href="#q16-codex-会泄露我的文件内容吗" aria-label="Permalink to &quot;Q16：Codex 会泄露我的文件内容吗？&quot;">​</a></h3><p>A：不会。Codex 处理你的文件内容是为了完成任务，不会将其分享给第三方。你的数据受到 OpenAI 的隐私政策保护。</p><h3 id="q17-如何确保-codex-不会误删重要文件" tabindex="-1">Q17：如何确保 Codex 不会误删重要文件？ <a class="header-anchor" href="#q17-如何确保-codex-不会误删重要文件" aria-label="Permalink to &quot;Q17：如何确保 Codex 不会误删重要文件？&quot;">​</a></h3><p>A：</p><ol><li>使用&quot;默认权限&quot;模式，每次操作都经过你确认</li><li>操作重要文件前先备份</li><li>限制 Codex 的工作区范围</li></ol><hr><h2 id="技术支持" tabindex="-1">技术支持 <a class="header-anchor" href="#技术支持" aria-label="Permalink to &quot;技术支持&quot;">​</a></h2><h3 id="q18-codex-运行很慢怎么办" tabindex="-1">Q18：Codex 运行很慢怎么办？ <a class="header-anchor" href="#q18-codex-运行很慢怎么办" aria-label="Permalink to &quot;Q18：Codex 运行很慢怎么办？&quot;">​</a></h3><p>A：可能的原因和解决方案：</p><ul><li>网络连接不稳定 → 检查网络</li><li>任务过于复杂 → 拆分任务</li><li>服务器繁忙 → 稍后再试</li></ul><h3 id="q19-codex-无法访问某些文件夹" tabindex="-1">Q19：Codex 无法访问某些文件夹？ <a class="header-anchor" href="#q19-codex-无法访问某些文件夹" aria-label="Permalink to &quot;Q19：Codex 无法访问某些文件夹？&quot;">​</a></h3><p>A：检查工作区设置是否正确，以及该文件夹是否有读取权限。macOS 用户可能需要在全磁盘访问中允许 Codex。</p><h3 id="q20-如何获取帮助" tabindex="-1">Q20：如何获取帮助？ <a class="header-anchor" href="#q20-如何获取帮助" aria-label="Permalink to &quot;Q20：如何获取帮助？&quot;">​</a></h3><p>A：</p><ul><li>OpenAI 官方文档：<a href="https://help.openai.com" target="_blank" rel="noreferrer">https://help.openai.com</a></li><li>社区论坛：<a href="https://community.openai.com" target="_blank" rel="noreferrer">https://community.openai.com</a></li><li>本课程附录中的 <a href="./prep-checklist.html">课前准备清单</a></li></ul>',59)])])}const s=e(d,[["render",l]]);export{u as __pageData,s as default};
